fn reverse(v: &mut Vec<u64>) {
    let n = v.len();
    if n <= 1 {
        return; // empty or single-element vectors are already reversed
    }

    let mut i: usize = 0;
    let mut j: usize = n - 1;

    while i < j {
        v.swap(i, j);
        i += 1;
        j -= 1;
    }
}